pm.zn_page_custom_css:
/* Add negative top margin to Action Box */
@media screen and (min-width:1200px){
    .eluiddbbaa9a0 {margin-top:-25px;}    
}

/* Add top shadow to featured collections/banners section */
.zn_section.eluideb6f0d13 {box-shadow: inset 0 1px 0px rgba(0, 0, 0, 0.1), inset 0 2px 0px rgba(0, 0, 0, 0.07), inset 0 3px 0px rgba(0, 0, 0, 0.03);}

/*back to top round*/
.on--totop #totop {
    border-radius:50%!important;
}


/*newsletter*/
.kl-newsletter-field{
    box-shadow:none;
}
.form-control{border-radius:0;}

.kl-newsletter-submit {  width: 175px; }

.video-grid-overlay:after{background-image:none;}


.u-zindex-2{
    position:relative;
    bottom:50px;
}
@media only screen and (min-width: 768px) {
    .u-zindex-2{
         bottom:-50px;
    }
}

/* 
* On Large Screens, move the perspective image 45px top, to create an "off edge" effect
*/
@media screen and (min-width:1200px){
    .eluidd580c102 { margin-top:-45px; }
    /* Also make sure the margin is not applied in edit mode (Page Builder) */
    div.zn_edit_mode .eluidd580c102 { margin-top:0; }
}
/* On extra small screen, shift the image 15 px to the right */
@media screen and (max-width:767px){
    .eluidd580c102 {margin-right:-15px;}
}
